class User {
  constructor(name) {
    this.name = name;  // обычное свойство
  }

  // Геттер — вызывается при ЧТЕНИИ obj.fullName
  get fullName() {
    return this.name;  // при чтении возвращаем имя
  }

  // Сеттер — вызывается при ЗАПИСИ obj.fullName = "..."
  set fullName(value) {
    this.name = value;  // при записи записываем имя
  }
}

const u = new User("Alice");
console.log(u.fullName);  // Alice — вызывается get
u.fullName = "Bob";      // Bob — вызывается set
console.log(u.name);      // Bob

class Rectangle {
  constructor(width, height) {
    this.width = width;
    this.height = height;
  }

  get area() {
    return this.width * this.height;  // вычисляем при чтении
  }

  get perimeter() {
    return 2 * (this.width + this.height);  // периметр тоже вычисляем
  }
}

const r = new Rectangle(5, 3);
console.log(r.area);      // 15 — геттер считает
r.width = 10;             // меняем ширину
console.log(r.area);      // 30 — геттер считает заново!

