class Temperature {
  constructor(celsius) {
    this.celsius = celsius;  // значение в Цельсиях
  }

  get fahrenheit() {
    return this.celsius * 9/5 + 32;  // вычисляем Фаренгейт
  }

  set fahrenheit(value) {
    this.celsius = (value - 32) * 5/9;  // конвертируем обратно в Цельсии
  }
}

const t = new Temperature(0);
console.log(t.fahrenheit);  // 32 — геттер считает

t.fahrenheit = 212;        // сеттер конвертирует
console.log(t.celsius);     // 100 — температура в Цельсиях

