class Password {
  #value;  // приватное поле для хранения

  get hash() {
    // Геттер возвращает ХЕШ, а не пароль
    return this.#value ? this.#value.length + " chars" : "empty";
  }

  set password(value) {
    // Сеттер принимает пароль, проверяет и хранит
    if (value.length < 6) {
      throw "Password too short (min 6)";
    }
    this.#value = value;
  }
}

const p = new Password();
p.password = "secret123";  // сеттер: проверка → сохранение
console.log(p.hash);        // геттер: "8 chars"

