class Account {
  #balance;  // приватное хранилище

  constructor(initial) {
    this.#balance = initial;  // можно сразу
  }

  get balance() {
    return this.#balance;  // геттер защищает от прямого доступа
  }

  set deposit(value) {
    if (value <= 0) {
      throw "Deposit must be positive";  // валидация
    }
    this.#balance += value;  // только после проверки
  }

  set withdraw(value) {
    if (value > this.#balance) {
      throw "Insufficient funds";  // проверка
    }
    this.#balance -= value;
  }
}

const acc = new Account(100);
acc.deposit = 50;    // баланс 150
acc.withdraw = 30;   // баланс 120
console.log(acc.balance);  // 120

class Counter {
  static #count = 0;  // счётчик созданных экземпляров

  constructor() {
    Counter.#count++;  // инкрементируем при каждом new
  }

  static get instanceCount() {
    return Counter.#count;  // читаем через static get
  }
}

new Counter();
new Counter();
new Counter();
console.log(Counter.instanceCount);  // 3 — считаем экземпляры

class Rectangle {
  constructor(width, height) {
    // Обычные свойства — простые данные
    this._width = width;
    this._height = height;
  }

  // Геттер — вычисляет на лету
  get area() {
    return this._width * this._height;
  }

  // Сеттер — валидирует
  set width(v) {
    if (v <= 0) throw "Width must be > 0";
    this._width = v;
  }
}

const r = new Rectangle(5, 3);
console.log(r.area);    // 15 — геттер
r.width = 10;           // 10 — сеттер с валидацией
console.log(r.area);    // 30 — геттер пересчитал

class DateRange {
  constructor(start, end) {
    this.start = start;  // Date
    this.end = end;      // Date
  }

  get days() {
    const diff = this.end - this.start;
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
  }

  get isLong() {
    return this.days > 30;  // булево значение
  }
}

const trip = new DateRange(
  new Date("2026-01-01"),
  new Date("2026-01-15")
);
console.log(trip.days);    // 14
console.log(trip.isLong);  // false

